+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.internal.ErrorStateRenderer;
+import org.slf4j.LoggerFactory;
+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Stream;
+
+/** UC-002: View Veterinarians. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        Grid<Vet> grid = new Grid<>();
+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(vet -> vet.specialties().isEmpty()
+                ? "none" : String.join(", ", vet.specialties())).setHeader("Specialties");
+        grid.setSizeFull();
+        grid.setDataProvider(DataProvider.fromCallbacks(
+                query -> fetchPage(query.getOffset(), query.getLimit()),
+                query -> count()));
+
+        add(new H2("Veterinarians"), grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetchPage(int offset, int limit) {
+        try {
+            return repository.findPage(offset, limit);
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    // Grid callbacks also run after navigation, when router exception handling
+    // no longer applies. Replace the directory with the application's error view.
+    private void showError(DataAccessException exception) {
+        LoggerFactory.getLogger(VetsView.class).error("Unable to load veterinarians", exception);
+        UI ui = UI.getCurrent();
+        var router = ui.getInternals().getRouter();
+        NavigationState state = new NavigationState(router);
+        state.setNavigationTarget(ApplicationErrorView.class);
+        new ErrorStateRenderer(state).handle(new ErrorNavigationEvent(router,
+                ui.getInternals().getActiveViewLocation(), ui, NavigationTrigger.PROGRAMMATIC,
+                new ErrorParameter<>(Exception.class, exception)));
+    }
+}
